INSERT INTO `tentang_desas` (`id`, `populasi`, `luas_wilayah`, `jumlah_rumah_tangga`, `visi`, `misi`, `lokasi_desa`, `created_at`, `updated_at`, `sejarah_desa`, `gambar_sejarah`, `batas_utara`, `batas_timur`, `batas_selatan`, `batas_barat`, `jumlah_kk`, `jumlah_dusun`) VALUES
(2, 150, '66789', 6, 'Terwujudnya Desa yang Maju, Sehat, Mandiri, Sejahtera, dan Berbasis Teknologi Informasi untuk Meningkatkan Kualitas Hidup Masyarakat', 'Meningkatkan pelayanan desa berbasis digital.\nMewujudkan masyarakat yang sehat, produktif, dan berdaya saing.\nMendorong pertumbuhan ekonomi desa melalui pengembangan UMKM, pertanian, peternakan, dan potensi lokal berbasis teknologi dan inovasi.', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3952.962904058172!2d110.36313277532531!3d-7.793752492226281!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e7a5825fa6106c5%3A0x3ea4c521a5ed1133!2sJl.%20Malioboro%2C%20Sosromenduran%2C%20Gedong%20Tengen%2C%20Kota%20Yogyakarta%2C%20Daerah%20Istimewa%20Yogyakarta!5e0!3m2!1sid!2sid!4v1779758983749!5m2!1sid!2sid\" width=\"800\" height=\"600\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', '2026-05-25 18:31:13', '2026-06-07 19:29:38', 'Desa ini merupakan salah satu wilayah yang memiliki sejarah panjang dalam perkembangan masyarakat dan pembangunan daerah. Pada awalnya, desa ini terbentuk dari sebuah pemukiman kecil yang dihuni oleh beberapa keluarga yang menggantungkan hidup pada sektor pertanian, perkebunan, dan hasil alam lainnya.\nSemangat gotong royong dan kebersamaan masyarakat menjadi fondasi utama dalam membangun desa, mulai dari pembangunan sarana ibadah, pendidikan, jalan lingkungan, hingga fasilitas umum lainnya.', 'sejarah-desa/01KSHTZY485JR7Y8PDVDECC5R9.jpeg', 'Kujopko', 'litur', 'Lamina', 'Yusoku', 40, 4);
