INSERT INTO `village_potentials` (`id`, `title`, `slug`, `image`, `description`, `created_at`, `updated_at`) VALUES
(1, 'Tanah Yang subur', 'Tanah Yang subur', '01KSGSVAMSWZ1STQQAD8E6DY56.jpg', 'Tanah yang luas dan subur\nKetersediaan air yang melimpah', '2026-05-25 17:09:43', '2026-06-04 20:09:56'),
(2, 'UMKM DESA KRIPIK', 'umkm-desa-kripikUMKM DESA KRIPIK', '01KTAXDJRC2EEG2BR7HDC0BG98.jpg', 'Albaeta bermula dari melimpahnya hasil panen kentang yang dihasilkan kelompok petani kentang di daerah dataran tinggi Dieng. Dari hasil panen Kelompok petani kentang tersebut, awalnya kentang jenis agria ini diolah sekadar untuk suguhan tamu. Seiring berjalannya waktu, keripik kentang Albaeta Kemudian berkembang menjadi bisnis yang kini memiliki produk unggulan seperti varian keripik kentang original yang populer. Kini usaha tersebut telah mempekerjakan 12 orang karyawan.', '2026-06-04 20:32:22', '2026-06-04 20:32:22'),
(3, 'Daun Kemangi dan Peluang Bisnis UMKM', 'daun-kemangi-dan-peluang-bisnis-umkm', '01KTDH30DCKPMEBKA2C5WC38ZF.png', 'Sahabat Wirausaha, hampir di setiap warung pecel lele dan rumah makan Sunda, daun kemangi selalu hadir sebagai pelengkap yang dianggap biasa. Harganya murah, mudah didapat, dan sering kali luput dari perhatian serius sebagai komoditas bisnis. Padahal, tanaman dengan nama ilmiah Ocimum basilicum ini menyimpan potensi ekonomi yang lebih dari sekadar lalapan. Dari minyak atsiri untuk industri parfum Eropa, hingga produk herbal dan teh premium yang mulai dilirik pasar wellness global — daun kemangi sedang menunggu pelaku UMKM yang mau melihatnya lebih dari sekadar pelengkap lalapan. Tanaman indigenous adalah tanaman lokal asli yang sudah lama tumbuh dan dikonsumsi oleh masyarakat di suatu daerah secara turun-temurun — bukan tanaman introduksi (yang sengaja didatangkan dari luar).\n\nKondisi ini bukan kelemahan komoditas, tetapi justru menggambarkan celah: permintaan pasar nyata ada, konsumsi rutin ada, namun data pendukung kebijakan dan pembiayaan masih terbatas. Bagi pelaku UMKM, ini artinya persaingan formal dari sisi data dan regulasi relatif lebih longgar dibandingkan komoditas hortikultura \"besar\" yang sudah ramai.', '2026-06-05 20:54:36', '2026-06-05 20:54:36'),
(4, 'Perkebunan', 'perkebunan', '01KTDHDHYZ37HMA784SKSZN71R.jpg', 'Dengan luasnya tanah untuk sawah dan ladang, perkebunan merupakan salah satu contoh UMKM di desa yang utama. Perkebunan tersebut bisa Anda tanami sayur-mayur, mengingat semakin banyaknya masyarakat Indonesia yang sadar akan hidup sehat. Bila memiliki sebidang tanah atau kebun, jangan tunda untuk mencoba jenis usaha yang satu ini.', '2026-06-05 21:00:21', '2026-06-05 21:00:21'),
(5, 'UMKM Batik', 'umkm-batik', '01KTDHR9JPSCPKGZEMEDD5FM44.jpg', 'Sahabat Wirausaha, sebagai warga negara Indonesia, kita tahu bahwa batik bukan hanya sekedar hasil karya anak bangsa namun lebih dari itu. Batik merupakan identitas bangsa Indonesia dan warisan budaya dari para leluhur kita yang harus dilestarikan dan dikembangkan. Maka tak heran bila jumlah industri batik di Indonesia semakin banyak hingga kini. ', '2026-06-05 21:06:13', '2026-06-05 21:06:13');
INSERT INTO `village_services` (`id`, `icon`, `nama_layanan`, `slug`, `deskripsi`, `persyaratan`, `prosedur`, `estimasi_waktu`, `biaya`, `warna`, `status`, `created_at`, `updated_at`) VALUES
(1, 'file', 'Surat Keterangan Domisili', 'surat-keterangan-domisili', 'Surat Keterangan Domisili (SKD) adalah dokumen resmi yang dikeluarkan oleh pihak kelurahan/desa untuk membuktikan alamat tempat tinggal seseorang atau lokasi sebuah usaha, terutama jika berbeda dengan alamat yang tertera di e-KTP', '<ul><li><p>Surat pengantar dari Ketua RT dan RW setempat.</p></li><li><p>Fotokopi dan e-KTP asli.</p></li><li><p>Fotokopi dan Kartu Keluarga (KK) asli.</p></li><li><p>Bukti tempat tinggal (misal: tagihan listrik, air, atau surat perjanjian sewa/kontrak).</p></li><li><p>Pas foto ukuran 3×4</p></li></ul>', '<ul><li><p><strong>Membuat Pengantar:</strong> Datangi pengurus RT dan RW setempat untuk meminta surat pengantar dengan membawa fotokopi KTP dan KK.</p></li><li><p><strong>Datangi Kelurahan:</strong> Bawa surat pengantar RT/RW serta berkas persyaratan lainnya ke kantor kelurahan/desa setempat.</p></li><li><p><strong>Penerbitan:</strong> Petugas akan memverifikasi berkas dan mencetak Surat Keterangan Domisili. Proses ini umumnya hanya memakan waktu 1 hari kerja jika persyaratan lengkap.</p></li></ul>', '3 Jam', 'Gratis', 'red', 1, '2026-06-01 02:01:59', '2026-06-06 17:44:09'),
(2, 'book-open', 'Surat Keterangan Usaha', 'surat-keterangan-usaha', 'Surat Keterangan Usaha (SKU) adalah dokumen resmi yang dikeluarkan oleh pemerintah daerah (kelurahan/desa/kecamatan) untuk membuktikan bahwa seseorang memiliki dan menjalankan kegiatan usaha tertentu', '<ul><li><p>Surat pengantar dari RT dan RW.</p></li><li><p>Fotokopi KTP dan Kartu Keluarga (KK).</p></li><li><p>Pas foto terbaru diri atau lokasi usaha.</p></li><li><p>Formulir permohonan yang ditandatangani dan dibubuhi meterai (sesuaikan dengan kebijakan kelurahan).</p></li></ul>', '<ul><li><p><strong>Minta Pengantar RT/RW:</strong> Datangi pengurus RT dan RW setempat dengan membawa berkas identitas untuk meminta surat pengantar dan stempel.</p></li><li><p><strong>Datang ke Kelurahan/Desa:</strong> Bawa surat pengantar RT/RW beserta berkas lainnya ke kantor kelurahan atau balai desa. Di sana, Anda akan mengisi formulir pembuatan SKU.</p></li><li><p><strong>Verifikasi:</strong> Pihak kelurahan akan memproses dan menerbitkan surat tersebut, yang kemudian ditandatangani dan dicap oleh lurah. Biasanya, proses ini gratis dan selesai dalam 1–3 hari kerja.</p></li></ul>', '1 Jam', 'Gratis', 'blue', 1, '2026-06-01 02:25:41', '2026-06-06 17:43:52');
